{"content": "import { Suspense } from 'react'
import { notFound } from 'next/navigation'
import { getProduct, getRelatedProducts } from '@/lib/products'

// Sync page: it prerenders the shop frame (nav + collection label + skeletons)
// as a static shell. params and searchParams are request-time, so they are
// passed as promises into Suspense-wrapped async children and awaited there,
// never at the top of the page.
export default function ProductPage({
  params,
  searchParams,
}: {
  params: Promise<{ slug: string }>
  searchParams: Promise<{ currency?: string }>
}) {
  return (
    <main>
      <p>Signal Shop collection</p>
      <Suspense fallback={<ProductSkeleton />}>
        <ProductDetails params={params} searchParams={searchParams} />
      </Suspense>
    </main>
  )
}

async function ProductDetails({
  params,
  searchParams,
}: {
  params: Promise<{ slug: string }>
  searchParams: Promise<{ currency?: string }>
}) {
  const { slug } = await params
  const { currency = 'USD' } = await searchParams
  const product = await getProduct(slug, currency)
  if (!product) notFound()

  return (
    <>
      <h1>{product.name}</h1>
      <p>{product.price}</p>
      {/* Related products stream in afterward, once the product details resolve. */}
      <Suspense fallback={<RelatedSkeleton />}>
        <RelatedProducts slug={slug} />
      </Suspense>
    </>
  )
}

async function RelatedProducts({ slug }: { slug: string }) {
  const related = await getRelatedProducts(slug)
  return (
    <section>
      <h2>Related products</h2>
      {related.map((item) => (
        <p key={item.slug}>{item.name}</p>
      ))}
    </section>
  )
}

function ProductSkeleton() {
  return (
    <div aria-hidden="true">
      <h1>Loading product…</h1>
      <p>Loading price…</p>
    </div>
  )
}

function RelatedSkeleton() {
  return (
    <section aria-hidden="true">
      <h2>Related products</h2>
      <p>Loading related products…</p>
    </section>
  )
}
